insert into public.puzzles (number, publish_date, format, title, prompt, lines, solution, why) values
  (1, '2026-10-22', 'order', 'Two sum', 'Order the lines so `two_sum` returns the indices of the two numbers that add up to `target`. One line doesn’t belong.', '[{"id":"a","text":"def two_sum(nums, target):","indent":0},{"id":"b","text":"seen = {}","indent":1},{"id":"c","text":"for i, num in enumerate(nums):","indent":1},{"id":"d","text":"need = target - num","indent":2},{"id":"e","text":"if need in seen:","indent":2},{"id":"f","text":"return [seen[need], i]","indent":3},{"id":"g","text":"seen[num] = i","indent":2},{"id":"h","text":"return []","indent":1},{"id":"x","text":"seen[i] = num","indent":2}]'::jsonb, '["a","b","c","d","e","f","g","h"]'::jsonb, 'The decoy `seen[i] = num` stores the map backwards. And `seen[num] = i` has to come after the check, or a number can match itself: try `[3, 3]` with target 6.'),
  (2, '2026-10-23', 'order', 'Palindrome check', 'Order the lines so `is_palindrome` uses two pointers to check whether `s` reads the same both ways. One line doesn’t belong.', '[{"id":"a","text":"def is_palindrome(s):","indent":0},{"id":"b","text":"left, right = 0, len(s) - 1","indent":1},{"id":"c","text":"while left < right:","indent":1},{"id":"d","text":"if s[left] != s[right]:","indent":2},{"id":"e","text":"return False","indent":3},{"id":"f","text":"left, right = left + 1, right - 1","indent":2},{"id":"g","text":"return True","indent":1},{"id":"x","text":"left, right = left - 1, right + 1","indent":2}]'::jsonb, '["a","b","c","d","e","f","g"]'::jsonb, 'The pointers start at the ends and move toward each other, so the decoy that moves them outward would run off the string. The comparison has to happen before the pointers move, or you skip the outermost pair.'),
  (3, '2026-10-24', 'order', 'Reverse a linked list', 'Order the lines so `reverse` flips a singly linked list in place and returns the new head. One line doesn’t belong.', '[{"id":"a","text":"def reverse(head):","indent":0},{"id":"b","text":"prev, curr = None, head","indent":1},{"id":"c","text":"while curr:","indent":1},{"id":"d","text":"nxt = curr.next","indent":2},{"id":"e","text":"curr.next = prev","indent":2},{"id":"f","text":"prev = curr","indent":2},{"id":"g","text":"curr = nxt","indent":2},{"id":"h","text":"return prev","indent":1},{"id":"x","text":"curr.next = curr","indent":2}]'::jsonb, '["a","b","c","d","e","f","g","h"]'::jsonb, 'Save `curr.next` first, because the next line overwrites it. The decoy `curr.next = curr` points a node at itself and makes an infinite loop.'),
  (4, '2026-10-25', 'order', 'Binary search', 'Order the lines so `search` returns the index of `target` in the sorted list `nums`, or -1. One line doesn’t belong.', '[{"id":"a","text":"def search(nums, target):","indent":0},{"id":"b","text":"lo, hi = 0, len(nums) - 1","indent":1},{"id":"c","text":"while lo <= hi:","indent":1},{"id":"d","text":"mid = (lo + hi) // 2","indent":2},{"id":"e","text":"if nums[mid] == target:","indent":2},{"id":"f","text":"return mid","indent":3},{"id":"g","text":"if nums[mid] < target:","indent":2},{"id":"h","text":"lo = mid + 1","indent":3},{"id":"i","text":"else:","indent":2},{"id":"j","text":"hi = mid - 1","indent":3},{"id":"k","text":"return -1","indent":1},{"id":"x","text":"mid = lo + hi // 2","indent":2}]'::jsonb, '["a","b","c","d","e","f","g","h","i","j","k"]'::jsonb, 'The decoy `mid = lo + hi // 2` is a precedence bug: `//` binds tighter than `+`, so it computes `lo + (hi // 2)`. The equality check comes first so the `else` only runs when the target is on the left.'),
  (5, '2026-10-26', 'order', 'Max subarray', 'Order the lines so `max_subarray` returns the largest sum of any contiguous slice of `nums` (Kadane’s algorithm). One line doesn’t belong.', '[{"id":"a","text":"def max_subarray(nums):","indent":0},{"id":"b","text":"best = cur = nums[0]","indent":1},{"id":"c","text":"for x in nums[1:]:","indent":1},{"id":"d","text":"cur = max(x, cur + x)","indent":2},{"id":"e","text":"best = max(best, cur)","indent":2},{"id":"f","text":"return best","indent":1},{"id":"x","text":"cur = max(cur, x)","indent":2}]'::jsonb, '["a","b","c","d","e","f"]'::jsonb, 'At each step you either extend the current run or start fresh at `x`, which is `max(x, cur + x)`. The decoy never adds anything, so it just tracks the largest single number.'),
  (6, '2026-10-27', 'order', 'Dedupe a sorted array', '`nums` is sorted and non-empty. Order the lines so `dedupe` removes duplicates in place and returns how many unique values are left. One line doesn’t belong.', '[{"id":"a","text":"def dedupe(nums):","indent":0},{"id":"b","text":"k = 1","indent":1},{"id":"c","text":"for i in range(1, len(nums)):","indent":1},{"id":"d","text":"if nums[i] != nums[k - 1]:","indent":2},{"id":"e","text":"nums[k] = nums[i]","indent":3},{"id":"f","text":"k += 1","indent":3},{"id":"g","text":"return k","indent":1},{"id":"x","text":"nums[i] = nums[k]","indent":3}]'::jsonb, '["a","b","c","d","e","f","g"]'::jsonb, '`k` is where the next unique value goes, so you write first and then advance it. The decoy copies in the wrong direction and overwrites values you haven’t read yet.'),
  (7, '2026-10-28', 'order', 'First unique character', 'Order the lines so `first_unique` returns the index of the first character that appears only once in `s`, or -1. One line doesn’t belong.', '[{"id":"a","text":"def first_unique(s):","indent":0},{"id":"b","text":"counts = {}","indent":1},{"id":"c","text":"for ch in s:","indent":1},{"id":"d","text":"counts[ch] = counts.get(ch, 0) + 1","indent":2},{"id":"e","text":"for i, ch in enumerate(s):","indent":1},{"id":"f","text":"if counts[ch] == 1:","indent":2},{"id":"g","text":"return i","indent":3},{"id":"h","text":"return -1","indent":1},{"id":"x","text":"counts[ch] = 1","indent":2}]'::jsonb, '["a","b","c","d","e","f","g","h"]'::jsonb, 'It takes two passes: count everything first, then scan in order for a count of 1. The decoy resets each count to 1, so every character would look unique.')
insert into public.puzzles (number, publish_date, format, title, prompt, lines, solution, hint, why) values
  (1, '2026-10-22', 'bug', 'Largest number', '`largest` should return the biggest number in a non-empty list. One line is wrong.', '[{"text":"def largest(nums):","indent":0},{"text":"best = 0","indent":1},{"text":"for n in nums:","indent":1},{"text":"if n > best:","indent":2},{"text":"best = n","indent":3},{"text":"return best","indent":1}]'::jsonb, '{"bug":1,"fix":"best = nums[0]"}'::jsonb, 'It works for `[3, 9, 4]`. Try `[-5, -2, -8]`.', 'Starting at `0` assumes some number beats zero. With all negatives, nothing does, so it returns `0`, which isn’t even in the list. Start from the first element instead.'),
  (2, '2026-10-23', 'bug', 'Fibonacci', '`fib(n)` should return the nth Fibonacci number, where `fib(0)` is 0 and `fib(1)` is 1. One line is wrong.', '[{"text":"def fib(n):","indent":0},{"text":"a, b = 0, 1","indent":1},{"text":"for _ in range(n):","indent":1},{"text":"a, b = b, a + b","indent":2},{"text":"return b","indent":1}]'::jsonb, '{"bug":4,"fix":"return a"}'::jsonb, 'Trace `fib(0)`. The loop never runs. What comes back?', 'After `n` steps, `a` holds `fib(n)` and `b` is already one ahead. Returning `b` is off by one: `fib(0)` gives 1 and `fib(2)` gives 2.'),
  (3, '2026-10-24', 'bug', 'Average', '`average` should return the mean of a non-empty list of numbers. One line is wrong.', '[{"text":"def average(nums):","indent":0},{"text":"total = 0","indent":1},{"text":"for n in nums:","indent":1},{"text":"total += n","indent":2},{"text":"return total // len(nums)","indent":1}]'::jsonb, '{"bug":4,"fix":"return total / len(nums)"}'::jsonb, 'What does `average([1, 2])` return?', '`//` is floor division, so the fractional part is thrown away: `average([1, 2])` returns `1` instead of `1.5`. Plain `/` keeps it.'),
  (4, '2026-10-25', 'bug', 'Shared default', '`add_item` should return a new list with `item` in it unless you pass your own `bag`. One line is wrong.', '[{"text":"def add_item(item, bag=[]):","indent":0},{"text":"if bag is None:","indent":1},{"text":"bag = []","indent":2},{"text":"bag.append(item)","indent":1},{"text":"return bag","indent":1}]'::jsonb, '{"bug":0,"fix":"def add_item(item, bag=None):"}'::jsonb, 'Call `add_item(1)` and then `add_item(2)`. What does the second call return?', 'A default value is built once, when the function is defined, so every call without `bag` appends to the same list: the second call returns `[1, 2]`. Defaulting to `None` makes the `is None` check do its job.'),
  (5, '2026-10-26', 'bug', 'Binary search', '`search` should return the index of `target` in the sorted list `xs`, or `-1` if it isn’t there. One line is wrong.', '[{"text":"def search(xs, target):","indent":0},{"text":"lo, hi = 0, len(xs) - 1","indent":1},{"text":"while lo < hi:","indent":1},{"text":"mid = (lo + hi) // 2","indent":2},{"text":"if xs[mid] == target:","indent":2},{"text":"return mid","indent":3},{"text":"if xs[mid] < target:","indent":2},{"text":"lo = mid + 1","indent":3},{"text":"else:","indent":2},{"text":"hi = mid - 1","indent":3},{"text":"return -1","indent":1}]'::jsonb, '{"bug":2,"fix":"while lo <= hi:"}'::jsonb, 'Try `search([5], 5)`.', '`hi` is an inclusive index, so a range where `lo == hi` still holds one candidate. Stopping at `lo < hi` skips it: `search([5], 5)` never looks and returns `-1`.'),
  (6, '2026-10-27', 'bug', 'Palindrome', '`is_palindrome` should return `True` when `s` reads the same both ways, like `"racecar"`. One line is wrong.', '[{"text":"def is_palindrome(s):","indent":0},{"text":"i, j = 0, len(s)","indent":1},{"text":"while i < j:","indent":1},{"text":"if s[i] != s[j]:","indent":2},{"text":"return False","indent":3},{"text":"i, j = i + 1, j - 1","indent":2},{"text":"return True","indent":1}]'::jsonb, '{"bug":1,"fix":"i, j = 0, len(s) - 1"}'::jsonb, 'On the first pass with `"racecar"`, what is `s[j]`?', '`len(s)` is one past the last index, so the very first `s[j]` raises `IndexError`. The right pointer has to start at `len(s) - 1`.'),
  (7, '2026-10-28', 'bug', 'Dedupe, keep order', '`dedupe` should drop repeated items and keep the first of each, in order. One line is wrong.', '[{"text":"def dedupe(items):","indent":0},{"text":"seen = set()","indent":1},{"text":"out = []","indent":1},{"text":"for x in items:","indent":1},{"text":"if x in seen:","indent":2},{"text":"seen.add(x)","indent":3},{"text":"out.append(x)","indent":3},{"text":"return out","indent":1}]'::jsonb, '{"bug":4,"fix":"if x not in seen:"}'::jsonb, '`seen` starts empty. Does anything ever get added to it?', 'The condition is inverted. `seen` starts empty, so `x in seen` is never true, nothing is ever added, and `dedupe` always returns `[]`. It should act on items it has not seen yet.')
